import {GameEngine,JOBS,BUILDINGS,GADGETS,HOUSE_DOOR} from './engine.js';
import {perimeterLayout} from './perimeter.js';
export const GUARD_POSTS=Object.freeze({auto:{name:'Automatic'},north:{name:'North watch',x:504,y:-100},south:{name:'South gate',x:504,y:620},east:{name:'East watch',x:1140,y:260},west:{name:'West watch',x:-320,y:260},house:{name:'Farmhouse',x:740,y:300}});
export function ensureCommand(s){s.command??={repairsFirst:false,queue:false,emergencies:false,fallback:false};for(const p of s.people){p.workPlan??={enabled:false,jobs:[p.job],base:p.job};p.guardPost??='auto';}}
export function validCommand(s){
 if(!s||!Array.isArray(s.people))return false;
 const c=s?.command;if(c!==undefined&&(!c||['repairsFirst','queue','emergencies','fallback'].some(k=>typeof c[k]!=='boolean')))return false;
 return !s?.people?.some(p=>(p.guardPost!==undefined&&!Object.hasOwn(GUARD_POSTS,p.guardPost))||(p.workPlan!==undefined&&(!p.workPlan||typeof p.workPlan.enabled!=='boolean'||(p.workPlan.restore!==undefined&&typeof p.workPlan.restore!=='boolean')||!Object.hasOwn(JOBS,p.workPlan.base)||!Array.isArray(p.workPlan.jobs)||p.workPlan.jobs.length<1||p.workPlan.jobs.length>6||new Set(p.workPlan.jobs).size!==p.workPlan.jobs.length||p.workPlan.jobs.some(j=>!Object.hasOwn(JOBS,j)))));
}
export function installFarmCommand(Engine){
 const proto=Engine.prototype,runPeople=proto.runPeople,nextSite=proto.nextSite,buildWork=proto.buildWork,defendWork=proto.defendWork,restore=proto.restore,start=proto.start;
 proto.start=function(...args){const result=start.apply(this,args);ensureCommand(this.s);this.commandClock=0;this.commandBreaches=null;return result;};
 proto.restore=function(raw){let parsed;try{parsed=JSON.parse(raw);}catch{return restore.call(this,raw);}if(!validCommand(parsed?.s))return {error:'Invalid farm command settings.'};const result=restore.call(this,raw);if(result.ok){ensureCommand(this.s);this.commandClock=0;this.commandBreaches=null;}return result;};
 proto.setWorkPlan=function(id,jobs,enabled=true){ensureCommand(this.s);const p=this.s.people.find(p=>p.id===id);if(!p||!Array.isArray(jobs)||!jobs.length||jobs.length>6||jobs.some(j=>!Object.hasOwn(JOBS,j))||new Set(jobs).size!==jobs.length)return false;const base=p.workPlan.enabled?p.workPlan.base:p.job;p.workPlan={enabled:!!enabled,jobs:[...jobs],base,restore:!enabled};if(!enabled&&!p.expeditionId&&!p.away&&!p.order){this.setJob(id,base);p.workPlan.restore=false;}return true;};
 proto.setGuardPost=function(id,post){const p=this.s.people.find(p=>p.id===id);if(!p||!Object.hasOwn(GUARD_POSTS,post))return false;p.guardPost=post;p.post=null;return true;};
 proto.moveConstruction=function(id,delta){const sites=this.s.sites,i=sites.findIndex(s=>s.id===id),j=i+delta;if(i<0||![-1,1].includes(delta)||j<0||j>=sites.length)return false;[sites[i],sites[j]]=[sites[j],sites[i]];ensureCommand(this.s);this.s.command.queue=true;return true;};
 proto.commandNeed=function(job){const s=this.s;if(job==='rest')return true;if(job==='defender')return s.phase==='night'||s.zombies.some(z=>z.hp>0);if(s.phase!=='day')return false;if(job==='builder')return !!s.sites.length||!!s.house.project||s.farmHp<this.maxFarmHealth()||s.fences.some(f=>f.hp<f.maxHp);if(job==='medic')return this.level('clinic')>0&&s.people.some(p=>!p.expeditionId&&p.hp<p.maxHp);if(job==='farmer')return s.plots.some(p=>p.growth>=0||s.seeds>0);if(job==='scout')return s.phaseDuration-s.phaseTime>35;return false;};
 proto.workExplanation=function(p){if(p.expeditionId)return 'On expedition — home priorities suspended';if(p.away>0)return 'Scouting away from home';if(p.order)return 'Following your direct order';if(!p.workPlan?.enabled)return 'Manual job assignment';const needed=p.workPlan.jobs.find(j=>this.commandNeed(j));return needed?`First available priority: ${JOBS[needed]}`:'No priority needs work — resting';};
 proto.constructionReport=function(){return this.s.sites.map((site,index)=>{const spec=site.kind==='building'?BUILDINGS[site.building].levels[site.level-1]:GADGETS[site.gadget];return {id:site.id,index,name:this.siteName(site),progress:site.progress,paid:spec.cost,remaining:Math.floor(spec.cost*(1-site.progress)),reason:site.perimeter&&!this.boundarySafe(site.rect)?'Unsafe: infected nearby':site.kind==='building'&&this.s.phase!=='day'?'Waiting for daylight':!this.s.people.some(p=>!p.expeditionId&&!p.away&&p.job==='builder')?'Needs a builder at home':'Ready'};});};
 proto.breachCount=function(){return perimeterLayout().filter(slot=>!this.s.fences.some(f=>f.perimeter===slot.perimeter&&f.hp>0)).length;};
 proto.commandReadiness=function(){const home=this.s.people.filter(p=>!p.expeditionId&&!p.away);return [{label:'Armed defenders at home',value:home.filter(p=>p.job==='defender'&&p.tool==='gun').length,ok:home.some(p=>p.job==='defender'&&p.tool==='gun')},{label:'Shells',value:this.s.ammo,ok:this.s.ammo>5},{label:'Farmhouse integrity',value:Math.round(100*this.s.farmHp/this.maxFarmHealth())+'%',ok:this.s.farmHp>=this.maxFarmHealth()*.5},{label:'Boundary gaps',value:this.breachCount(),ok:this.breachCount()===0},{label:'Generator power',value:this.powered()?'Online':'Offline',ok:this.powered()}];};
 proto.runPeople=function(dt){ensureCommand(this.s);this.commandClock=(this.commandClock||0)-dt;if(this.commandClock<=0){this.commandClock=1;const c=this.s.command;
  for(const p of this.s.people){if(p.expeditionId||p.away>0||p.order)continue;if(!p.workPlan.enabled){if(p.workPlan.restore){this.setJob(p.id,p.workPlan.base);p.workPlan.restore=false;}continue;}let job=p.workPlan.jobs.find(j=>this.commandNeed(j))||'rest';if(c.emergencies&&this.s.phase==='night'&&p.workPlan.jobs.includes('defender'))job='defender';if(c.emergencies&&this.s.phase==='day'&&this.s.farmHp<this.maxFarmHealth()*.35&&p.workPlan.jobs.includes('builder'))job='builder';if(p.job!==job)this.setJob(p.id,job);}
  if(this.s.phase==='night'){const gaps=this.breachCount();if(this.commandBreaches!==null&&gaps>this.commandBreaches)this.notice(`PERIMETER BREACH: ${gaps} open boundary sections. Check guard posts or order a fallback.`,true);this.commandBreaches=gaps;}else this.commandBreaches=this.breachCount();
 }runPeople.call(this,dt);};
 proto.nextSite=function(p){ensureCommand(this.s);if(this.s.command.repairsFirst&&(this.s.farmHp<this.maxFarmHealth()||this.s.fences.some(f=>f.hp<f.maxHp&&(!f.perimeter||this.boundarySafe(f)))))return null;if(!this.s.command.queue)return nextSite.call(this,p);return this.s.sites.filter(s=>(s.kind==='gadget'||this.s.phase==='day')&&(!s.perimeter||this.boundarySafe(s.rect))).sort((a,b)=>(b.priority||0)-(a.priority||0))[0]||null;};
 proto.buildWork=function(p,dt){ensureCommand(this.s);if(this.s.command.repairsFirst&&this.s.farmHp<this.maxFarmHealth()){if(p.task?.fix!=='house'){p.task={fix:'house',x:HOUSE_DOOR.x-50,y:HOUSE_DOOR.y+6};p.timer=1.5;}GameEngine.prototype.buildWork.call(this,p,dt);return;}if(this.s.command.repairsFirst&&this.s.fences.some(f=>f.hp<f.maxHp&&(!f.perimeter||this.boundarySafe(f)))){GameEngine.prototype.buildWork.call(this,p,dt);return;}buildWork.call(this,p,dt);};
 proto.defendWork=function(p,dt){ensureCommand(this.s);const post=this.s.command.fallback?GUARD_POSTS.house:GUARD_POSTS[p.guardPost];if(!post||p.guardPost==='auto'&&!this.s.command.fallback){defendWork.call(this,p,dt);return;}if(p.inside){p.inside=false;p.x=HOUSE_DOOR.x;p.y=HOUSE_DOOR.y+4;}p.panic=false;p.post??={};Object.assign(p.post,{x:post.x+(p.id%3-1)*18,y:post.y});this.walkTo(p,p.post,95,dt);p.status=this.s.command.fallback?'Falling back to farmhouse':`Holding ${post.name.toLowerCase()}`;};
}
